"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[76231],{3331:(e,n,r)=>{r.d(n,{R:()=>o,x:()=>s});var i=r(36672);const a={},t=i.createContext(a);function o(e){const n=i.useContext(t);return i.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(t.Provider,{value:n},e.children)}},83310:(e,n,r)=>{r.r(n),r.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>u,frontMatter:()=>o,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Arrestatie verricht in de moord op Bob Lee - vermeende moordenaar werkte ook in de techniek","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/nl/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14 april 2023","top_news":"Arrestatie verricht in de moord op Bob Lee - vermeende moordenaar werkte ook in de techniek"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/nl/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/nl/2023/04/13"}}');var a=r(23420),t=r(3331);const o={localized_date:"14 april 2023",top_news:"Arrestatie verricht in de moord op Bob Lee - vermeende moordenaar werkte ook in de techniek"},s="2023-04-14",d={},l=[{value:"Arrestatie verricht in de moord op Bob Lee - vermeende moordenaar werkte ook in de techniek",id:"arrestatie-verricht-in-de-moord-op-bob-lee---vermeende-moordenaar-werkte-ook-in-de-techniek",level:2},{value:"Verbod op YouTube-DL Hosting baant de weg naar geprivatiseerde censuur",id:"verbod-op-youtube-dl-hosting-baant-de-weg-naar-geprivatiseerde-censuur",level:2},{value:"De kunst van autotechniek",id:"de-kunst-van-autotechniek",level:2},{value:"Apple zal tegen 2025 100 procent gerecycled kobalt gebruiken in batterijen",id:"apple-zal-tegen-2025-100-procent-gerecycled-kobalt-gebruiken-in-batterijen",level:2},{value:"We hebben de opstartsnelheid van Podman met een factor 6 verhoogd.",id:"we-hebben-de-opstartsnelheid-van-podman-met-een-factor-6-verhoogd",level:2},{value:"Verbetering van Tailscale via Apple&#39;s open source",id:"verbetering-van-tailscale-via-apples-open-source",level:2},{value:"Geanimeerde tekeningen",id:"geanimeerde-tekeningen",level:2},{value:"Amazon CodeWhisperer, gratis voor individueel gebruik, is nu algemeen beschikbaar.",id:"amazon-codewhisperer-gratis-voor-individueel-gebruik-is-nu-algemeen-beschikbaar",level:2},{value:"Google heeft in 2023 al zes producten uit de markt gehaald.",id:"google-heeft-in-2023-al-zes-producten-uit-de-markt-gehaald",level:2},{value:"Nvidia RTX Remix Runtime Open Source Nu beschikbaar",id:"nvidia-rtx-remix-runtime-open-source-nu-beschikbaar",level:2}];function c(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,a.jsx)(n.h2,{id:"arrestatie-verricht-in-de-moord-op-bob-lee---vermeende-moordenaar-werkte-ook-in-de-techniek",children:"Arrestatie verricht in de moord op Bob Lee - vermeende moordenaar werkte ook in de techniek"}),"\n",(0,a.jsxs)(n.p,{children:["(",(0,a.jsx)(n.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/"}),").\nEr is een arrestatie verricht voor de moord op technisch directeur Bob Lee, en de vermeende moordenaar werkte ook in de technologiesector en kende Lee. De politie vond Lee en de verdachte samen in een auto die op naam van de verdachte staat, en beweert dat er een soort confrontatie plaatsvond in het voertuig en mogelijk werd voortgezet nadat Lee was vertrokken. De berichtgeving over Lee's dood is samengevoegd met andere recente tegenslagen en misdaden in San Francisco, hoewel dit niet de werkelijke ervaring van de meeste San Franciscanen weergeeft."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nDe moord op een technisch directeur in San Francisco heeft discussies op gang gebracht over factoren als dakloosheid, geestelijke gezondheid, drugsverslaving en armoede die tot de misdaad kunnen hebben geleid, maar commentatoren waarschuwen voor generalisaties. Er is ook discussie over het gebruik van statistieken versus persoonlijke anekdotes bij het beoordelen van misdaadcijfers, en een behoefte aan een gemeenschapsgerichte aanpak om de complexe problemen van dakloosheid, verslaving en misdaad aan te pakken. Gebruikers benadrukken het belang van het evalueren van misdaadniveaus in relatie tot armoede in plaats van verschillende culturen te vergelijken en geen overhaaste conclusies te trekken op basis van \xe9\xe9n geval."]}),"\n",(0,a.jsx)(n.h2,{id:"verbod-op-youtube-dl-hosting-baant-de-weg-naar-geprivatiseerde-censuur",children:"Verbod op YouTube-DL Hosting baant de weg naar geprivatiseerde censuur"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Origineel"}),'.\nEen Duitse rechtbank heeft Uberspace aansprakelijk gesteld voor het hosten van de website van youtube-dl - een open-source tool waarmee YouTube-inhoud kan worden gedownload. Uberspace waarschuwt dat het vonnis kan leiden tot geprivatiseerde censuur en gaat in beroep tegen het vonnis, hoewel de rechtbank stelt dat Uberspace "aansprakelijk kan worden gesteld voor het betwijfelen van de geldigheid van een takedown-verzoek", zelfs wanneer het niet duidelijk was dat de tool de wet overtrad.']}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nHet verbieden van YouTube-DL hosting wordt gezien als een stap in de richting van geprivatiseerde censuur, waarbij de RIAA en MPAA geld en macht laten prevaleren boven fatsoen. De rol van intellectueel eigendom bij het beperken van de informatiestroom wordt besproken, waarbij verschillende standpunten worden aangedragen, waaronder beperking van de reikwijdte en de duur. Gebruikers stellen alternatieven voor en hekelen de afhankelijkheid van GitHub, terwijl ze decentralisatie en problemen met beveiliging door onduidelijkheid bij kopieerbeveiliging bespreken."]}),"\n",(0,a.jsx)(n.h2,{id:"de-kunst-van-autotechniek",children:"De kunst van autotechniek"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://www.howacarworks.com/video-course",children:"Origineel"}),".\nThe Art of Auto Engineering is een complete videocursus bestaande uit 122+ lessen met 20 uur beeldmateriaal waarin elk onderdeel van een auto tot in detail wordt uitgelegd, van de basis tot geavanceerde autotechniek. De cursus gaat vergezeld van een handboek van 200 pagina's en is online of in iOS en Android apps beschikbaar voor een eenmalige betaling van $25 met levenslange toegang, en is professioneel gefilmd in 4K-kwaliteit met volledige ondertiteling. De cursus wordt door kijkers geprezen om zijn boeiende instructie en uitstekende productiewaarde."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nGebruikers van Hacker News delen ervaringen en bevelen bronnen aan voor het leren over autotechniek, waaronder interactieve videocursussen en specifieke automodellen. Commentatoren bespreken de voordelen van het begrijpen van automonteurs, de beperkingen van het alleen vertrouwen op AI, en geven tips voor doe-het-zelf autoreparaties. Daarnaast discussi\xebren gebruikers over het nut van betaalde cursussen en hulpmiddelen, en sommigen bekritiseren het verschijnen van advertenties voor betaalde klassen op de site."]}),"\n",(0,a.jsx)(n.h2,{id:"apple-zal-tegen-2025-100-procent-gerecycled-kobalt-gebruiken-in-batterijen",children:"Apple zal tegen 2025 100 procent gerecycled kobalt gebruiken in batterijen"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Origineel"}),".\nApple heeft het plan bekendgemaakt om tegen 2025 100% gerecycled kobalt te gebruiken in alle door Apple ontworpen batterijen, naast volledig gerecyclede zeldzame aardmetalen voor magneten en 100% gerecycled tin voor printplaten. Ze streven ernaar om uitsluitend gerecyclede en hernieuwbare materialen te gebruiken en halen nu al meer dan 95% van het wolfraam, bijna driekwart van de zeldzame aardmetalen en meer dan tweederde van het aluminium uit 100% gerecycled materiaal. Apple maakt gebruik van augmented reality (AR) om de demontage van apparaten voor recyclingpartners te begeleiden en de terugwinning van zeldzame aardmetalen te bevorderen."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple heeft zijn plan aangekondigd om tegen 2025 100% gerecycled kobalt te gebruiken in batterijen en het plastic afval te verminderen, maar gebruikers discussi\xebren over de doeltreffendheid van deze veranderingen en over de vraag of het bedrijf zijn recyclingtechnologie openbaar moet maken. Het debat over door de gebruiker vervangbare batterijen gaat door, met argumenten dat ze negatief zijn voor het milieu, terwijl anderen suggereren dat recyclingmethoden en het verlengen van de levensduur van duurzame producten dit probleem kunnen oplossen. De inzet van Apple voor recyclebare materialen en een koolstofneutrale toeleveringsketen wordt geprezen, maar bekritiseerd vanwege het ontwerp en de kobalttoeleveringsketen. Gebruikers bespreken de levensduur van iPhones en Android-telefoons, en recyclingmethoden voor batterijen. Sommige gebruikers stellen MagSafe-batterijen voor als primaire batterij voor iPhones, terwijl anderen de effici\xebntie ervan in twijfel trekken."]}),"\n",(0,a.jsx)(n.h2,{id:"we-hebben-de-opstartsnelheid-van-podman-met-een-factor-6-verhoogd",children:"We hebben de opstartsnelheid van Podman met een factor 6 verhoogd."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Origineel"}),".\nRed Hat's container engine, Podman, heeft de opstartsnelheid met een factor 6 verhoogd door onnodige processen te verwijderen en kleine ineffici\xebnties aan te pakken die van invloed zijn op kritieke toepassingen zoals auto's, waar het bijna-realtime opstarten van containers essentieel is. Het team gebruikte transi\xebnte opslag en bood workarounds voor kernelproblemen, wat resulteerde in het sneller opstarten van containers. Het gebruik van de --transient-store optie is ideaal voor randapparatuur, hoewel mixed mode containers niet worden ondersteund."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nRed Hat's Podman ziet een verzesvoudiging van de opstartsnelheid voor auto's, hoewel Discussion Service-gebruikers de overcomplicatie van moderne auto's bespreken en zorgen uiten over betrouwbaarheid en onderhoud. De discussie loopt uiteen in debatten over het recht op reparatie, het gebruik van microservices en containers, en de balans tussen technologische vooruitgang en bruikbaarheid."]}),"\n",(0,a.jsx)(n.h2,{id:"verbetering-van-tailscale-via-apples-open-source",children:"Verbetering van Tailscale via Apple's open source"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Origineel"}),'.\nHet Tailscale-team gebruikte de open source van Apple om bugs met betrekking tot de netwerkinterface te debuggen voor hun 1.36-release, vertrouwend op ifconfig om de actieve netwerkinterface te bepalen. Wanneer Tailscale is geconfigureerd om een exit node te gebruiken, wordt het de standaard route, waardoor een fix nodig is om netwerkverzoeken consequent te "binden" aan de actieve netwerkinterface zonder looping verkeer te veroorzaken. SIOCGIFDELEGATE, beschikbaar via ioctl, maakt het mogelijk om de onderliggende fysieke interface te verkrijgen en werd ge\xefmplementeerd in de code van Tailscale voor macOS en iOS.']}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nDiscussion Service-gebruikers bespreken de voordelen en uitdagingen van open en closed source software in de verbetering van Tailscale via de open source van Apple. Sommige betalende klanten geven prioriteit aan de reputatie van het open source kernproduct van Tailscale, terwijl sommigen specifieke problemen met Tailscale aankaarten, zoals problemen met toegang tot netwerkshares op Windows 11 en potenti\xeble batterijafvoer op iOS-apparaten. De discussie benadrukt het belang van het overwegen van verschillende perspectieven en de toenemende tractie van Tailscale ten opzichte van Zerotier vanwege zijn mesh-systeem en continue inzet van nieuwe functies, maar inkomsten en moat zorgen bestaan voor sommige productgebruikers."]}),"\n",(0,a.jsx)(n.h2,{id:"geanimeerde-tekeningen",children:"Geanimeerde tekeningen"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://fairanimateddrawings.com/site/home",children:"Origineel"}),".\nDe 'Animated Drawings' repository op Github implementeert het algoritme beschreven in het artikel \"A Method for Automatically Animating Children's Drawings of the Human Figure\", waardoor gebruikers zelf animaties kunnen maken met hun eigen handgetekende personages. Het installatieproces is eenvoudig, en configuratiebestanden kunnen worden aangepast om verschillende opties te wijzigen, waaronder uitvoerformaten en achtergrondafbeeldingen. De repository biedt ook scripts en modellen voor het animeren van persoonlijke tekeningen, en een browser-gebaseerde demo is beschikbaar voor snel en eenvoudig gebruik."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nHet Fair Animated Drawings project animeert tekeningen met code, beschikbaar in een browser-gebaseerde en GitHub versie. Gebruikers zijn ge\xefnteresseerd in het potentieel ervan voor zakelijke idee\xebn en hopen op een Android app-versie. Een relevant werk over niet-fotorealistische pose estimation genaamd Gesture3D lijkt van toepassing op een specifieke use case, en YC Summer 2023 aanvragen zijn open."]}),"\n",(0,a.jsx)(n.h2,{id:"amazon-codewhisperer-gratis-voor-individueel-gebruik-is-nu-algemeen-beschikbaar",children:"Amazon CodeWhisperer, gratis voor individueel gebruik, is nu algemeen beschikbaar."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Origineel"}),".\nAmazon CodeWhisperer, een real-time AI-coderingshulpmiddel, is nu algemeen beschikbaar en omvat een CodeWhisperer Individual-tier dat gratis is voor alle ontwikkelaars om te gebruiken. De tool helpt ontwikkelaars snel en veilig code te schrijven zonder hun IDE te verlaten. CodeWhisperer biedt suggesties voor algemene gebruikssituaties in verschillende talen en kan codesuggesties filteren of markeren die lijken op bepaalde open-source trainingsgegevens, waardoor het risico op het gebruik van mogelijk bevooroordeelde of gebrekkige code wordt beperkt."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer is nu algemeen beschikbaar en ondersteunt verschillende talen, waaronder Python, Java, JavaScript, TypeScript en C#. Hoewel Copilot naar verluidt beter is dan CodeWhisperer, is laatstgenoemde een nuttig hulpmiddel dat ertoe kan leiden dat AI-gegenereerde code de norm wordt. Daarnaast heeft Amazon CodeGuru Reviewer gelanceerd, een AI-tool die code scant om problemen te identificeren en fixes aan te bevelen voor effici\xebntie en kostenbesparing."]}),"\n",(0,a.jsx)(n.h2,{id:"google-heeft-in-2023-al-zes-producten-uit-de-markt-gehaald",children:"Google heeft in 2023 al zes producten uit de markt gehaald."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Original"}),".\nGoogle heeft in de eerste vier maanden van 2023 zes producten gesloten, waaronder de programmeerwedstrijd Code Jam, social media platform Google Currents, de Street View app, wearable tech Google Jacquard, cloud gaming service Google Stadia en draadloze router Google OnHub. Hoewel sommige van deze producten meer dan tien jaar oud waren, heeft Google kritiek te verduren gekregen vanwege zijn gewoonte om populaire diensten abrupt te be\xebindigen."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle heeft in 2023 zes producten stopgezet, met zorgen over transparantie en productetikettering, en gebrek aan ondersteuning voor mislukte pogingen waaronder Google Glass en Google Plus. Hoewel de cloud-afdeling groeit met een marktaandeel van 10%, zijn er zorgen over de betrokkenheid van klanten en ontwikkelaars en het account-killing algoritme. Gebruikers debatteren over oplossingen en kosten om de nauwkeurigheid van ChatGPT te verbeteren, terwijl Google's reputatie om projecten op te geven kritiek oplevert over productondersteuning voor consumenten."]}),"\n",(0,a.jsx)(n.h2,{id:"nvidia-rtx-remix-runtime-open-source-nu-beschikbaar",children:"Nvidia RTX Remix Runtime Open Source Nu beschikbaar"}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Origineel"}),".\nNvidia heeft de RTX Remix runtime vrijgegeven, een open source modding platform voor het remasteren van klassieke DirectX 8 en 9 games met path tracing, AI-verbeterde texturen en door de gebruiker gemaakte assets. Met de RTX Remix creator toolkit kunnen modders nieuwe assets en lichten toewijzen binnen een geremasterde sc\xe8ne, en AI-tools gebruiken om het uiterlijk van elke asset opnieuw op te bouwen. De RTX Remix runtime daarentegen neemt een game scene op, vervangt assets tijdens het afspelen en injecteert RTX technologie, zoals path tracing, DLSS 3 en Reflex in de game."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia heeft zijn open-source RTX Remix Runtime vrijgegeven waardoor gebruikers oudere games met ray tracing in real-time kunnen spelen, hoewel niet alle games zullen werken. Gebruikers van Hacker News bespreken het belang van open-source drivers versus eigen drivers, de reputatie van Nvidia en de slechte prestaties van RTX op niet-Nvidia hardware. Gebruikers speculeren ook over mogelijke vriendjespolitiek en stellen voor cryptocurrency-ontwikkelaars te steunen die alleen GPU proof-of-work schema's implementeren. E\xe9n gebruiker wijst op Remedy's ontwikkeling van remakes van Max Payne PC games met behulp van Remix en bespreekt de framepacing en stotterproblemen van de technologie."]})]})}function u(e={}){const{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}}}]);